SELECT d.d_year, cp.cp_department, SUM(cr.cr_return_amount) AS total_return_amount, COUNT(*) AS return_count FROM catalog_returns cr JOIN date_dim d ON cr.cr_returned_date_sk = d.d_date_sk JOIN catalog_page cp ON cr.cr_catalog_page_sk = cp.cp_catalog_page_sk WHERE d.d_year = 1939 AND cp.cp_department = 'DEPARTMENT' GROUP BY d.d_year, cp.cp_department ORDER BY total_return_amount DESC
